Method.Source:
// Get the fieldStr for all attributes that will be used in rebate setting should be covered here
internal static str getFieldStrFromAttributeLink(GUPPricingAttributeLink _attrLink)
{
    switch(_attrLink.PriceAttributeClassId)
    {
        case classnum(GUPPricingAttributeCustTableAccountNum):
            return fieldStr(CustTable, AccountNum);
        case classnum(GUPPricingAttributeCustTableLineDisc):
            return fieldStr(CustTable, LineDisc);
        case classnum(GUPPricingAttributeCustTableMultiLineDisc):
            return fieldStr(CustTable, MultiLineDisc);
        case classnum(GUPPricingAttributeCustTablePriceGroup):
            return fieldStr(CustTable, PriceGroup);
        case classnum(GUPPricingAttributeCustTableEndDisc):
            return fieldStr(CustTable, EndDisc);
        case classnum(GUPPricingAttributeSalesTableInventSiteId):
            return fieldStr(SalesTable, InventSiteId);
        case classnum(GUPPricingAttributeSalesTableDlvMode):
            return fieldStr(SalesTable, DlvMode);
        case classnum(GUPPricingAttributeInventTableItemId):
            return fieldStr(InventTable, ItemId);
        case classnum(GUPPricingAttributeInventTableProduct):
            return fieldStr(InventTable, Product);
        case classnum(GUPPricingAttributeInventTablePrimaryVendorId):
            return fieldStr(InventTable, PrimaryVendorId);
        case classnum(GUPPricingAttributeSalesLineDlvMode):
            return fieldStr(SalesLine, DlvMode);
        // Added
        // Customer and product attributes
        case classNum(GUPPricingAttributeEcoResAttribute):
            // if private label
            if (_attrLink.AttributeDataType == 'TrueFalse')
            {
                return fieldStr(GUPEcoResInstanceAttributeValuesView, BooleanValue);
            }
            else
            {
                return fieldStr(GUPEcoResInstanceAttributeValuesView, TextValue);
            }
        default:
            return _attrLink.FieldName;
    }
}
